    setne cl
    movzx ecx, cl
    push rcx
    mov rcx, qword [rsp+0]
    sub rsp, 32
    call $exit
    add rsp, 40
    xor eax, eax
ret_main:
    mov rsp, rbp
    pop rbp
    ret

